class TestDeletionOnlyPatchIsNotErased:
    """A file that still exists must never have its whole patch trimmed away.

    omit_deletion_hunks drops every hunk that carries no added line, so a diff made
    only of removals used to reduce to "". Callers cannot tell that apart from "no diff",
    and the compressed path in pr_processing then dropped the file from the prompt while
    adding it to no list at all, so the model was never told the file had changed.
    """

    DELETIONS_ONLY = "@@ -1,40 +1,4 @@\n-removed one\n-removed two\n kept"

    def test_deletion_only_patch_survives_for_a_modified_file(self):
        out = handle_patch_deletions(
            self.DELETIONS_ONLY, "old\n", "kept\n", "svc.py", EDIT_TYPE.MODIFIED)
        assert out != ""
        assert "-removed one" in out
        assert "-removed two" in out

    def test_fully_emptied_file_patch_survives_when_edit_type_is_modified(self):
        # The shape from #2682. PR #2683 fixed the line-number converter, but
        # handle_patch_deletions runs first on the compressed path, so the converter
        # never saw this patch and the content was still lost there.
        out = handle_patch_deletions(
            "@@ -1,3 +0,0 @@\n-a\n-b\n-c", "a\nb\nc\n", "", "emptied.py", EDIT_TYPE.MODIFIED)
        assert out != ""
        for line in ("-a", "-b", "-c"):
            assert line in out

    def test_deletion_only_hunk_is_still_omitted_when_another_hunk_survives(self):
        # The token-saving intent is preserved: a deletion-only hunk is still dropped
        # whenever at least one other hunk carries added lines.
        out = handle_patch_deletions(
            "@@ -1,3 +1,1 @@\n-a\n-b\n-c\n@@ -10,2 +8,3 @@\n ctx\n+added",
            "a\nb\nc\n", "ctx\nadded\n", "mixed.py", EDIT_TYPE.MODIFIED)
        assert "+added" in out
        assert "-a" not in out

    def test_genuinely_deleted_file_still_reports_no_patch(self):
        # The real deletion path is untouched: a deleted file returns None.
        out = handle_patch_deletions(
            "@@ -1,3 +0,0 @@\n-a\n-b\n-c", "a\nb\nc\n", "", "gone.py", EDIT_TYPE.DELETED)
        assert out is None
